// ── GLOBAL ELEVATION GRID ─────────────────────────────────────────────────────
// Real terrain, so mountains stop being rectangles.
//
// Generated by scripts/validation/build/build_elevation_grid.py from AWS
// Terrain Tiles (SRTM / GMTED2010 / ETOPO1 and others — attribution in
// docs/validation/ELEVATION-ATTRIBUTION.md). Four releases in a row fixed the
// same defect in the hand-drawn mountain boxes (VALIDATION Parts 42-45); this
// is what ends that class of bug instead of patching one range at a time.
//
// Two layers on a 0.25-degree grid (~28 km):
//   MEAN — mean elevation of the cell's land: where a station stands.
//   MAX  — highest point in the cell: what a ray has to clear.
//
// LOADING mirrors the foF2 table: a precached binary asset, fetched once, and
// until it arrives every caller falls back to the box model — so the app works
// the instant it opens and the grid only ever makes it more accurate.
//
// Part of the original work of Cpl Angeles-Gonzalez, Ezekiel S., USMC.
// Project signature: HFCALC-AG-EZK-USMC-v1

const GRID_URL = 'elevation-grid.bin';

var MEAN = null, MAX = null, META = null;

// Byte -> metres. Keep in step with encode_elev() in the build script.
export function decodeElev(v) {
  return v < 128 ? v * 10 : 1280 + (v - 128) * 60;
}

function unRle(bytes, n) {
  var out = new Uint8Array(n);
  var i = 0, o = 0;
  while (i < bytes.length && o < n) {
    var b = bytes[i++];
    if (b === 0) {
      var run = bytes[i] | (bytes[i + 1] << 8);
      i += 2;
      o += run;               // already zero-filled
    } else {
      out[o++] = b;
    }
  }
  return o === n ? out : null;
}

// Header: 'HFE1', uint16 nLat, uint16 nLon, float32 lat0, lon0, step;
// then two layers, each uint32 byte length + zero-run-length body.
export function parseElevationGrid(buffer) {
  try {
    var dv = new DataView(buffer);
    if (dv.getUint8(0) !== 0x48 || dv.getUint8(1) !== 0x46
        || dv.getUint8(2) !== 0x45 || dv.getUint8(3) !== 0x31) return null;
    var nLat = dv.getUint16(4, true), nLon = dv.getUint16(6, true);
    var lat0 = dv.getFloat32(8, true), lon0 = dv.getFloat32(12, true), step = dv.getFloat32(16, true);
    var o = 20, n = nLat * nLon;
    var lenA = dv.getUint32(o, true); o += 4;
    var mean = unRle(new Uint8Array(buffer, o, lenA), n); o += lenA;
    var lenB = dv.getUint32(o, true); o += 4;
    var max = unRle(new Uint8Array(buffer, o, lenB), n); o += lenB;
    if (!mean || !max || o !== buffer.byteLength) return null;
    return { meta: { nLat: nLat, nLon: nLon, lat0: lat0, lon0: lon0, step: step }, mean: mean, max: max };
  } catch (e) { return null; }
}

export function installElevationGrid(parsed) {
  if (!parsed || !parsed.mean || !parsed.max) return false;
  MEAN = parsed.mean; MAX = parsed.max; META = parsed.meta;
  return true;
}

// Tests and tools only: drop back to the box model.
export function uninstallElevationGrid() { MEAN = null; MAX = null; META = null; }

export function elevationGridReady() { return MEAN !== null; }
export function elevationGridMeta() { return META; }

export function loadElevationGrid(base) {
  if (MEAN) return Promise.resolve(true);
  return fetch((base || '') + GRID_URL)
    .then(function(r) { return r.ok ? r.arrayBuffer() : null; })
    .then(function(buf) { return buf ? installElevationGrid(parseElevationGrid(buf)) : false; })
    .catch(function() { return false; });
}

// Cell index for a point; longitude wraps, latitude clamps.
export function elevCell(lat, lon) {
  if (!META || typeof lat !== 'number' || typeof lon !== 'number'
      || !isFinite(lat) || !isFinite(lon)) return -1;
  var r = Math.floor((lat - META.lat0) / META.step);
  if (r < 0) r = 0; else if (r > META.nLat - 1) r = META.nLat - 1;
  var c = Math.floor((((lon - META.lon0) % 360) + 360) % 360 / META.step);
  if (c > META.nLon - 1) c = META.nLon - 1;
  return r * META.nLon + c;
}

// ICE SHEETS. Over Greenland and Antarctica the source mosaic carries BEDROCK,
// not ice surface — Greenland's ~3,200 m summit reads ~240 m in the grid,
// Vostok ~1,100 m against ~3,490 m. Those numbers are known to be wrong, so the
// grid answers "no data" there and the terrain model keeps its box figures
// (a 2,800 m ice-sheet highland) instead. Using a number known to be wrong
// because it came from "real data" would be the worst kind of confident
// answer. The Greenland outline is approximate and deliberately generous on
// the ice side; it may also swallow the eastern tip of Ellesmere Island, which
// then simply falls back to the box model too.
export function onIceSheet(lat, lon) {
  if (lat <= -60) return true;                                   // Antarctica
  if (lat >= 74) return lon >= -75 && lon <= -10;                // north Greenland
  if (lat >= 59.5) return lon >= -58 && lon <= -10;              // south Greenland
  return false;
}

// Metres, or null when the grid is not loaded or has no trustworthy value.
export function elevMean(lat, lon) {
  var i = elevCell(lat, lon);
  if (i < 0 || onIceSheet(lat, lon)) return null;
  return decodeElev(MEAN[i]);
}
export function elevMax(lat, lon) {
  var i = elevCell(lat, lon);
  if (i < 0 || onIceSheet(lat, lon)) return null;
  return decodeElev(MAX[i]);
}
